118	async fn get_version(
119	    State(s): State<Arc<Store>>,
120	    Path(id): Path<u64>,
121	) -> Result<Json<Value>, ApiError> {
122	    let d = s
123	        .get_version(id)
124	        .map_err(|e| lookup_error(e, "version", id))?;
125	    let mut collections = d.collections;
126	    collections.sort();
127	    Ok(Json(json!({
128	        "id": d.id,
129	        "saved_at": d.saved_at,
130	        "collections": collections,
131	    })))
