229	        .route("/versions/{id}", get(get_version))
230	        .route(
231	            "/versions/{id}/collections/{collection}/records",
232	            get(read_records),
233	        )
234	        .route(
235	            "/versions/{from}/collections/{collection}/diff/{to}",
236	            get(diff_versions),
237	        )
238	        .with_state(store)
