136	struct Inner {
137	    /// 各集合的当前数据；Vec 保存提交顺序。
138	    current: BTreeMap<String, Vec<Record>>,
139	    versions: Vec<VersionSnap>,
140	    next_id: u64,
141	    wal: fs::File,
142	}
