157	impl Store {
158	    /// 从数据目录加载或初始化存储，并完成崩溃恢复。
159	    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, String> {
160	        let data_dir = data_dir.as_ref().to_path_buf();
161	        fs::create_dir_all(&data_dir).map_err(|e| format!("create data dir: {e}"))?;
162	
163	        let mut current: BTreeMap<String, Vec<Record>> = BTreeMap::new();
164	        let mut versions: Vec<VersionSnap> = Vec::new();
165	
166	        // 1. 恢复最近一次快照（若存在）。
167	        let snap_path = data_dir.join("snapshot.json");
168	        if snap_path.exists() {
169	            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
170	            let state: PersistedState =
171	                serde_json::from_slice(&bytes).map_err(|e| format!("parse snapshot: {e}"))?;
172	            for c in state.collections {
173	                current.insert(c.name, c.records);
174	            }
175	            for v in state.versions {
176	                versions.push(VersionSnap {
177	                    id: v.id,
178	                    saved_at: v.saved_at,
179	                    data: v
180	                        .collections
181	                        .into_iter()
182	                        .map(|c| (c.name, c.records))
183	                        .collect(),
184	                });
185	            }
186	        }
187	        let next_id = versions.last().map(|v| v.id + 1).unwrap_or(1);
188	
189	        // 2. 重放快照之后的 WAL，并修复崩溃残留的残缺行。
190	        let wal_path = data_dir.join("wal.log");
191	        let mut valid_bytes = 0usize;
192	        if wal_path.exists() {
193	            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
194	            let mut rest = content.as_str();
195	            loop {
196	                if rest.is_empty() {
197	                    break;
198	                }
199	                let Some(nl) = rest.find('\n') else {
200	                    // 最后一行没有换行结尾：本服务的提交总是以换行结尾，故必为残缺行。
201	                    break;
202	                };
203	                let line = &rest[..nl];
204	                match serde_json::from_str::<CommitEvent>(line) {
205	                    Ok(event) => {
206	                        apply_commit(&mut current, event.collection, event.records);
207	                        valid_bytes += nl + 1;
208	                        rest = &rest[nl + 1..];
209	                    }
210	                    Err(_) => break,
211	                }
212	            }
213	            if valid_bytes < content.len() {
214	                let f = fs::OpenOptions::new()
215	                    .write(true)
216	                    .open(&wal_path)
217	                    .map_err(|e| format!("repair wal: {e}"))?;
218	                f.set_len(valid_bytes as u64)
219	                    .map_err(|e| format!("repair wal: {e}"))?;
220	                f.sync_all().ok();
221	            }
222	        }
223	
224	        // 3. 打开 WAL 供后续追加。
225	        let wal = fs::OpenOptions::new()
226	            .create(true)
227	            .append(true)
228	            .open(&wal_path)
229	            .map_err(|e| format!("open wal: {e}"))?;
230	
231	        Ok(Store {
232	            inner: Mutex::new(Inner {
233	                current,
234	                versions,
235	                next_id,
236	                wal,
237	            }),
238	            data_dir,
239	        })
240	    }
241	
242	    /// 批量写入：整批校验通过后原子提交，任一条不合法则整批拒绝、已有数据不变。
243	    pub fn write_batch(
244	        &self,
245	        collection: &str,
246	        batch: &[Value],
247	    ) -> Result<WriteOutcome, BatchError> {
248	        if collection.is_empty() {
249	            return Err(BatchError::Rejected(Rejection {
250	                index: 0,
251	                id: None,
252	                reason: "collection name must not be empty".to_string(),
253	            }));
254	        }
255	
256	        let mut st = self.inner.lock().unwrap();
257	
258	        // 阶段 1：逐条校验；任何失败都直接返回，状态未做任何修改。
259	        let mut seen: HashMap<&str, usize> = HashMap::with_capacity(batch.len());
260	        let mut prepared: Vec<Record> = Vec::with_capacity(batch.len());
261	        for (i, raw) in batch.iter().enumerate() {
262	            let rec = match raw {
263	                Value::Object(map) => map,
264	                _ => {
265	                    return Err(BatchError::Rejected(Rejection {
266	                        index: i,
267	                        id: None,
268	                        reason: "record must be a JSON object".to_string(),
269	                    }));
270	                }
271	            };
272	            let id = match rec.get("id") {
273	                None => {
274	                    return Err(BatchError::Rejected(Rejection {
275	                        index: i,
276	                        id: None,
277	                        reason: "missing primary key field \"id\"".to_string(),
278	                    }));
279	                }
280	                Some(Value::String(s)) if !s.is_empty() => s.as_str(),
281	                Some(Value::String(_)) => {
282	                    return Err(BatchError::Rejected(Rejection {
283	                        index: i,
284	                        id: None,
285	                        reason: "primary key \"id\" must be a non-empty string".to_string(),
286	                    }));
287	                }
288	                Some(_) => {
289	                    return Err(BatchError::Rejected(Rejection {
290	                        index: i,
291	                        id: None,
292	                        reason: "primary key \"id\" must be a string".to_string(),
293	                    }));
294	                }
295	            };
296	            if let Some(&first) = seen.get(id) {
297	                return Err(BatchError::Rejected(Rejection {
298	                    index: i,
299	                    id: Some(id.to_string()),
300	                    reason: format!(
301	                        "duplicate id \"{id}\" in the same batch (first at index {first})"
302	                    ),
303	                }));
304	            }
305	            for (field, value) in rec.iter() {
306	                if let Err(msg) = validate_value(value) {
307	                    return Err(BatchError::Rejected(Rejection {
308	                        index: i,
309	                        id: Some(id.to_string()),
310	                        reason: format!("field \"{field}\": {msg}"),
311	                    }));
312	                }
313	            }
314	            seen.insert(id, i);
315	            prepared.push(rec.clone());
316	        }
317	
318	        // 阶段 2：与集合中已有记录冲突检查——同主键但内容不同即拒绝整批。
319	        if let Some(existing) = st.current.get(collection) {
320	            for (i, rec) in prepared.iter().enumerate() {
321	                let id = rec["id"].as_str().unwrap();
322	                if let Some(old) = existing.iter().find(|r| r["id"] == id)
323	                    && old != rec
324	                {
325	                    return Err(BatchError::Rejected(Rejection {
326	                        index: i,
327	                        id: Some(id.to_string()),
328	                        reason: format!(
329	                            "collection \"{collection}\" already contains a different record with id \"{id}\""
330	                        ),
331	                    }));
332	                }
333	            }
334	        }
335	
336	        // 阶段 3：先持久化（追加 WAL 并 fsync），成功后才更新内存并确认成功。
337	        let event = CommitEvent {
338	            collection: collection.to_string(),
339	            records: prepared.clone(),
340	        };
341	        append_wal(&mut st.wal, &event).map_err(BatchError::Persist)?;
342	
343	        let existing = st.current.entry(collection.to_string()).or_default();
344	        let mut inserted = 0usize;
345	        for rec in prepared {
346	            let id = rec["id"].as_str().unwrap();
347	            match existing.iter().position(|r| r["id"] == id) {
348	                Some(pos) => existing[pos] = rec, // 内容相同：幂等写入
349	                None => {
350	                    existing.push(rec);
351	                    inserted += 1;
352	                }
353	            }
354	        }
355	
356	        Ok(WriteOutcome {
357	            collection: collection.to_string(),
358	            accepted: batch.len(),
359	            inserted,
360	        })
361	    }
