363	    /// 把当前各集合数据固化为只读版本，返回版本标识与保存时间。
364	    pub fn save_version(&self) -> Result<VersionSummary, String> {
365	        let mut st = self.inner.lock().unwrap();
366	        let id = st.next_id;
367	        let saved_at = now_ms();
368	        let data: HashMap<String, Vec<Record>> = st
369	            .current
370	            .iter()
371	            .map(|(name, records)| (name.clone(), records.clone()))
372	            .collect();
373	        st.versions.push(VersionSnap { id, saved_at, data });
374	        st.next_id += 1;
375	
376	        // 固化完整状态到快照文件，然后清空 WAL（旧提交已包含在快照中）。
377	        persist_state(&self.data_dir, &st)?;
378	        truncate_wal(&mut st.wal, &self.data_dir.join("wal.log"))?;
379	
380	        Ok(VersionSummary { id, saved_at })
381	    }
