383	    /// 查询指定版本内指定集合的全部记录（字段顺序与写入时一致）。
384	    pub fn read_records(
385	        &self,
386	        version_id: u64,
387	        collection: &str,
388	    ) -> Result<Vec<Record>, LookupError> {
389	        let st = self.inner.lock().unwrap();
390	        let version = st
391	            .versions
392	            .iter()
393	            .find(|v| v.id == version_id)
394	            .ok_or(LookupError::VersionNotFound)?;
395	        version
396	            .data
397	            .get(collection)
398	            .cloned()
399	            .ok_or(LookupError::CollectionNotFound)
400	    }
