402	    /// 比较同一集合在两个已保存版本之间的差异。
403	    ///
404	    /// 只读取快照，不生成新版本、不改写任何数据。记录内容比较与写入冲突检测一致：
405	    /// 字段顺序不影响判定，字段名与字段值相同即视为同一条记录。
406	    pub fn diff_versions(
407	        &self,
408	        from: u64,
409	        to: u64,
410	        collection: &str,
411	    ) -> Result<DiffOutcome, DiffError> {
412	        let st = self.inner.lock().unwrap();
413	        let from_v = st
414	            .versions
415	            .iter()
416	            .find(|v| v.id == from)
417	            .ok_or(DiffError::FromVersionNotFound)?;
418	        let to_v = st
419	            .versions
420	            .iter()
421	            .find(|v| v.id == to)
422	            .ok_or(DiffError::ToVersionNotFound)?;
423	        if from > to {
424	            return Err(DiffError::OutOfOrder);
425	        }
426	        let from_recs = from_v
427	            .data
428	            .get(collection)
429	            .ok_or(DiffError::CollectionNotFoundInFrom)?;
430	        let to_recs = to_v
431	            .data
432	            .get(collection)
433	            .ok_or(DiffError::CollectionNotFoundInTo)?;
434	
435	        // BTreeMap 迭代顺序即主键 id 的字节序升序。
436	        let from_map: BTreeMap<&str, &Record> = from_recs
437	            .iter()
438	            .map(|r| (r["id"].as_str().expect("validated record"), r))
439	            .collect();
440	        let to_map: BTreeMap<&str, &Record> = to_recs
441	            .iter()
442	            .map(|r| (r["id"].as_str().expect("validated record"), r))
443	            .collect();
444	
445	        let mut added = Vec::new();
446	        let mut dropped = Vec::new();
447	        let mut changed = Vec::new();
448	        for (id, before) in &from_map {
449	            match to_map.get(id) {
450	                None => added.push((*before).clone()),
451	                Some(after) if **after != **before => changed.push(ChangedRecord {
452	                    before: (*before).clone(),
453	                    after: (*after).clone(),
454	                }),
455	                Some(_) => {}
456	            }
457	        }
458	        for (id, after) in &to_map {
459	            if !from_map.contains_key(id) {
460	                dropped.push((*after).clone());
461	            }
462	        }
463	
464	        Ok(DiffOutcome {
465	            from,
466	            to,
467	            collection: collection.to_string(),
468	            added,
469	            dropped,
470	            changed,
471	        })
472	    }
