518	fn append_wal(wal: &mut fs::File, event: &CommitEvent) -> Result<(), String> {
519	    let mut line = serde_json::to_vec(event).map_err(|e| format!("encode wal: {e}"))?;
520	    line.push(b'\n');
521	    wal.write_all(&line)
522	        .and_then(|_| wal.flush())
523	        .and_then(|_| wal.sync_all())
524	        .map_err(|e| format!("wal append: {e}"))
525	}
