601	/// 递归校验字段值：仅允许字符串、整数、布尔、null 与嵌套对象；
602	/// 浮点数与数组一律拒绝。
603	fn validate_value(v: &Value) -> Result<(), String> {
604	    match v {
605	        Value::Null | Value::Bool(_) | Value::String(_) => Ok(()),
606	        Value::Number(n) if n.is_i64() || n.is_u64() => Ok(()),
607	        Value::Number(_) => Err("number must be an integer".to_string()),
608	        Value::Object(map) => {
609	            for (k, child) in map {
610	                validate_value(child).map_err(|e| format!("{k}: {e}"))?;
611	            }
612	            Ok(())
613	        }
614	        Value::Array(_) => Err("arrays are not allowed".to_string()),
615	    }
616	}
