66	fn request(addr: &str, method: &str, path: &str, body: Option<&str>) -> RawResponse {
67	    let mut stream = TcpStream::connect(addr).unwrap();
68	    let mut req = format!("{method} {path} HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n");
69	    if let Some(b) = body {
