481	async fn concurrent_writes_and_snapshots_never_see_half_batches() {
482	    let s = Arc::new(spawn_server().await);
483	    let writers = 8usize;
484	    let batches = 12usize;
485	    let batch_size = 5usize;
486	
487	    let mut handles = Vec::new();
488	    for w in 0..writers {
489	        let addr = s.addr.clone();
490	        handles.push(tokio::spawn(async move {
491	            for b in 0..batches {
492	                let mut recs = String::from("[");
493	                for i in 0..batch_size {
494	                    if i > 0 {
495	                        recs.push(',');
496	                    }
497	                    recs.push_str(&format!(
498	                        "{{\"id\":\"w{w}-b{b}-r{i}\",\"w\":{w},\"b\":{b},\"i\":{i}}}"
499	                    ));
500	                }
501	                recs.push(']');
502	                let payload = format!(r#"{{"records":{recs}}}"#);
503	                let addr2 = addr.clone();
504	                let r = tokio::task::spawn_blocking(move || {
505	                    request(&addr2, "POST", "/collections/items/records", Some(&payload))
506	                })
507	                .await
508	                .unwrap();
509	                assert_eq!(r.status, 200, "batch {w}/{b}: {}", r.body);
510	            }
511	        }));
512	    }
513	
514	    // 并发持续保存快照。
515	    let saver_addr = s.addr.clone();
516	    let saver = tokio::spawn(async move {
517	        let mut saved = Vec::new();
518	        for _ in 0..20 {
519	            let addr2 = saver_addr.clone();
520	            let r = tokio::task::spawn_blocking(move || request(&addr2, "POST", "/versions", None))
521	                .await
522	                .unwrap();
523	            assert_eq!(r.status, 201);
524	            saved.push(r.body["id"].as_u64().unwrap());
525	            tokio::time::sleep(std::time::Duration::from_millis(2)).await;
526	        }
527	        saved
528	    });
529	
530	    for h in handles {
531	        h.await.unwrap();
532	    }
533	    let saved = saver.await.unwrap();
534	
535	    // 每个快照中，任一批次要么完整出现、要么完全不出现。
536	    for vid in saved {
537	        let addr = s.addr.clone();
538	        let r = tokio::task::spawn_blocking(move || {
539	            request(
540	                &addr,
541	                "GET",
542	                &format!("/versions/{vid}/collections/items/records"),
543	                None,
544	            )
545	        })
546	        .await
547	        .unwrap();
548	        assert_eq!(r.status, 200);
549	        // 以 (w,b) 分组计数，每个已出现的批次必须是完整的 batch_size 条。
550	        let mut counts = std::collections::HashMap::new();
551	        for rec in r.body["records"].as_array().unwrap() {
552	            let key = (rec["w"].as_u64().unwrap(), rec["b"].as_u64().unwrap());
553	            *counts.entry(key).or_insert(0u64) += 1;
554	        }
555	        for ((w, b), n) in &counts {
556	            assert_eq!(
557	                *n, batch_size as u64,
558	                "half batch w{w} b{b}: {n}/{batch_size}"
559	            );
560	        }
561	    }
562	
563	    // 最终全部写入均可见（无丢失的已确认批次）。
564	    let r = request(&s.addr, "POST", "/versions", None);
565	    let final_v = r.body["id"].as_u64().unwrap();
566	    let r = request(
567	        &s.addr,
568	        "GET",
569	        &format!("/versions/{final_v}/collections/items/records"),
570	        None,
571	    );
572	    assert_eq!(
573	        r.body["records"].as_array().unwrap().len(),
574	        writers * batches * batch_size
575	    );
576	}
