1	//! 持久化存储：集合、当前数据状态与不可变版本快照。
2	//!
3	//! 持久化采用“快照文件 + 追加式 WAL”：
4	//! - `snapshot.json` 以“临时文件 + 原子重命名”落盘，包含全部已保存版本及其快照数据、
5	//!   以及保存时刻各集合的当前数据；
6	//! - `wal.log` 逐行追加已确认提交的批量写入（每行一个 JSON，以换行结尾）；
7	//! - 启动时先恢复快照，再顺序重放 WAL；末尾若存在崩溃残留的残缺行则截断，
8	//!   因此未完成（未 fsync）的写入在重启后不会产生任何记录。
9	//!
10	//! 所有提交与保存都在同一把 `Mutex` 下完成，保证线性一致：快照要么包含
11	//! 整批已提交写入，要么完全不包含，不会出现半批数据。
12	
13	use serde::{Deserialize, Serialize};
14	use serde_json::{Map, Value};
15	use std::collections::{BTreeMap, HashMap};
16	use std::fs;
17	use std::io::Write;
18	use std::path::{Path, PathBuf};
19	use std::sync::Mutex;
20	use std::time::{SystemTime, UNIX_EPOCH};
21	
22	/// 一条记录即保留字段顺序的 JSON 对象，主键为其中的 `id` 字段。
23	pub type Record = Map<String, Value>;
24	
25	/// 一次写入被业务规则拒绝：定位到批次内的记录位置、主键（若可识别）与原因。
26	#[derive(Debug, Clone, Serialize)]
27	pub struct Rejection {
28	    pub index: usize,
29	    pub id: Option<String>,
30	    pub reason: String,
31	}
32	
33	/// 写入失败：整批被拒绝（400）或持久化失败（500）。
34	#[derive(Debug)]
35	pub enum BatchError {
36	    Rejected(Rejection),
37	    Persist(String),
38	}
39	
40	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
41	pub enum LookupError {
42	    VersionNotFound,
43	    CollectionNotFound,
44	}
45	
46	/// 版本差异查询失败：版本/集合不存在（404）或起始版本晚于目标版本（400）。
47	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
48	pub enum DiffError {
49	    FromVersionNotFound,
50	    ToVersionNotFound,
51	    CollectionNotFoundInFrom,
52	    CollectionNotFoundInTo,
53	    /// 起始版本晚于目标版本（版本号随保存动作递增）。
54	    OutOfOrder,
55	}
56	
57	/// 两个版本中都存在但内容不同的一条记录：修改前与修改后的完整记录。
58	#[derive(Debug, Clone, Serialize)]
59	pub struct ChangedRecord {
60	    pub before: Record,
61	    pub after: Record,
62	}
63	
64	/// 同一集合在两个已保存版本之间的差异；三个列表均按主键 id 字节序升序。
65	#[derive(Debug, Clone, Serialize)]
66	pub struct DiffOutcome {
67	    pub from: u64,
68	    pub to: u64,
69	    pub collection: String,
70	    /// 仅存在于起始版本的记录（在目标版本中被删除）。
71	    pub added: Vec<Record>,
72	    /// 仅存在于目标版本的记录（新写入）。
73	    pub dropped: Vec<Record>,
74	    /// 两个版本中都存在但内容不同的记录。
75	    pub changed: Vec<ChangedRecord>,
76	}
77	
78	#[derive(Debug, Clone, Serialize)]
79	pub struct WriteOutcome {
80	    pub collection: String,
81	    /// 批次中被接受的记录数（等于整批大小）。
82	    pub accepted: usize,
83	    /// 实际新增的记录数（与已有记录完全相同的写入幂等，不计入）。
84	    pub inserted: usize,
85	    /// 被新内容覆盖的已有记录数（仅 replace=true 时可能大于 0；
86	    /// 与已有记录完全相同的写入幂等，不计入）。
87	    pub replaced: usize,
88	}
89	
90	#[derive(Debug, Clone, Serialize)]
91	pub struct VersionSummary {
92	    pub id: u64,
93	    /// 保存时间（Unix 纪元毫秒）。
94	    pub saved_at: u64,
95	}
96	
97	#[derive(Debug, Clone, Serialize)]
98	pub struct VersionDetail {
99	    pub id: u64,
100	    pub saved_at: u64,
101	    /// 该版本快照中包含的集合名。
102	    pub collections: Vec<String>,
103	}
104	
105	/// 一个已保存版本的完整只读快照。
106	struct VersionSnap {
107	    id: u64,
108	    saved_at: u64,
109	    data: HashMap<String, Vec<Record>>,
110	}
111	
112	/// WAL 中的事件：已确认提交的一批记录。
113	#[derive(Serialize, Deserialize)]
114	struct CommitEvent {
115	    collection: String,
116	    records: Vec<Record>,
117	}
118	
119	#[derive(Serialize, Deserialize)]
120	struct PersistedCollection {
121	    name: String,
122	    records: Vec<Record>,
123	}
124	
125	#[derive(Serialize, Deserialize)]
126	struct PersistedVersion {
127	    id: u64,
128	    saved_at: u64,
129	    collections: Vec<PersistedCollection>,
130	}
131	
132	/// `snapshot.json` 的完整内容。
133	#[derive(Serialize, Deserialize)]
134	struct PersistedState {
135	    versions: Vec<PersistedVersion>,
136	    collections: Vec<PersistedCollection>,
137	}
138	
139	struct Inner {
140	    /// 各集合的当前数据；Vec 保存提交顺序。
141	    current: BTreeMap<String, Vec<Record>>,
142	    versions: Vec<VersionSnap>,
143	    next_id: u64,
144	    wal: fs::File,
145	}
146	
147	/// 整个服务的状态。
148	pub struct Store {
149	    inner: Mutex<Inner>,
150	    data_dir: PathBuf,
151	}
152	
153	fn now_ms() -> u64 {
154	    SystemTime::now()
155	        .duration_since(UNIX_EPOCH)
156	        .map(|d| d.as_millis() as u64)
157	        .unwrap_or(0)
158	}
159	
160	impl Store {
161	    /// 从数据目录加载或初始化存储，并完成崩溃恢复。
162	    pub fn open(data_dir: impl AsRef<Path>) -> Result<Self, String> {
163	        let data_dir = data_dir.as_ref().to_path_buf();
164	        fs::create_dir_all(&data_dir).map_err(|e| format!("create data dir: {e}"))?;
165	
166	        let mut current: BTreeMap<String, Vec<Record>> = BTreeMap::new();
167	        let mut versions: Vec<VersionSnap> = Vec::new();
168	
169	        // 1. 恢复最近一次快照（若存在）。
170	        let snap_path = data_dir.join("snapshot.json");
171	        if snap_path.exists() {
172	            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
173	            let state: PersistedState =
174	                serde_json::from_slice(&bytes).map_err(|e| format!("parse snapshot: {e}"))?;
175	            for c in state.collections {
176	                current.insert(c.name, c.records);
177	            }
178	            for v in state.versions {
179	                versions.push(VersionSnap {
180	                    id: v.id,
181	                    saved_at: v.saved_at,
182	                    data: v
183	                        .collections
184	                        .into_iter()
185	                        .map(|c| (c.name, c.records))
186	                        .collect(),
187	                });
188	            }
189	        }
190	        let next_id = versions.last().map(|v| v.id + 1).unwrap_or(1);
191	
192	        // 2. 重放快照之后的 WAL，并修复崩溃残留的残缺行。
193	        let wal_path = data_dir.join("wal.log");
194	        let mut valid_bytes = 0usize;
195	        if wal_path.exists() {
196	            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
197	            let mut rest = content.as_str();
198	            loop {
199	                if rest.is_empty() {
200	                    break;
201	                }
202	                let Some(nl) = rest.find('\n') else {
203	                    // 最后一行没有换行结尾：本服务的提交总是以换行结尾，故必为残缺行。
204	                    break;
205	                };
206	                let line = &rest[..nl];
207	                match serde_json::from_str::<CommitEvent>(line) {
208	                    Ok(event) => {
209	                        apply_commit(&mut current, event.collection, event.records);
210	                        valid_bytes += nl + 1;
211	                        rest = &rest[nl + 1..];
212	                    }
213	                    Err(_) => break,
214	                }
215	            }
216	            if valid_bytes < content.len() {
217	                let f = fs::OpenOptions::new()
218	                    .write(true)
219	                    .open(&wal_path)
220	                    .map_err(|e| format!("repair wal: {e}"))?;
221	                f.set_len(valid_bytes as u64)
222	                    .map_err(|e| format!("repair wal: {e}"))?;
223	                f.sync_all().ok();
224	            }
225	        }
226	
227	        // 3. 打开 WAL 供后续追加。
228	        let wal = fs::OpenOptions::new()
229	            .create(true)
230	            .append(true)
231	            .open(&wal_path)
232	            .map_err(|e| format!("open wal: {e}"))?;
233	
234	        Ok(Store {
235	            inner: Mutex::new(Inner {
236	                current,
237	                versions,
238	                next_id,
239	                wal,
240	            }),
241	            data_dir,
242	        })
243	    }
244	
245	    /// 批量写入：整批校验通过后原子提交，任一条不合法则整批拒绝、已有数据不变。
246	    ///
247	    /// `replace=false`（默认）时同主键不同内容整批拒绝；`replace=true` 时允许用
248	    /// 新内容覆盖同主键的已有记录。无论哪种模式，同一请求内主键重复、非法记录等
249	    /// 仍然整批拒绝，不会出现部分写入/替换。
250	    pub fn write_batch(
251	        &self,
252	        collection: &str,
253	        batch: &[Value],
254	        replace: bool,
255	    ) -> Result<WriteOutcome, BatchError> {
256	        if collection.is_empty() {
257	            return Err(BatchError::Rejected(Rejection {
258	                index: 0,
259	                id: None,
260	                reason: "collection name must not be empty".to_string(),
261	            }));
262	        }
263	
264	        let mut st = self.inner.lock().unwrap();
