#[test]
fn rejects_batch_atomically_with_detailed_reason() {
    let dir = temp_dir();
    let store = Store::open(&dir).unwrap();
    let ok = store
        .write_batch("users", &[json!({"id": "u1", "name": "Ada", "age": 36})], false)            .unwrap();
    assert_eq!(ok.inserted, 1);

    // 第二条非法，整批拒绝；u2 不得残留。
    let err = store
        .write_batch(
            "users",
            &[
                json!({"id": "u2", "score": 100}),
                json!({"id": "u3", "score": 9.5}),
            ],
        )
        .unwrap_err();
    match err {
        BatchError::Rejected(r) => {
            assert_eq!(r.index, 1);
            assert_eq!(r.id.as_deref(), Some("u3"));
            assert!(r.reason.contains("integer"));
        }
        BatchError::Persist(e) => panic!("{e}"),
    }

    // 缺主键。
    let err = store
        .write_batch("users", &[json!({"name": "NoId"})], false)            .unwrap_err();
    match err {
        BatchError::Rejected(r) => assert!(r.reason.contains("missing primary key")),
        _ => panic!(),
    }

    // 同批重复主键。
    let err = store
        .write_batch("users", &[json!({"id": "d1"}), json!({"id": "d1"})], false)            .unwrap_err();
    match err {
        BatchError::Rejected(r) => assert!(r.reason.contains("duplicate id")),
        _ => panic!(),
    }

    // 同主键不同内容 → 拒绝。
    let err = store
        .write_batch("users", &[json!({"id": "u1", "name": "Ada", "age": 37})], false)            .unwrap_err();
    match err {
        BatchError::Rejected(r) => assert!(r.reason.contains("different record")),
        _ => panic!(),
    }

    // 数组字段拒绝。
    let err = store
        .write_batch("users", &[json!({"id": "u4", "tags": ["a"]})], false)            .unwrap_err();
    match err {
        BatchError::Rejected(r) => assert!(r.reason.contains("arrays")),
        _ => panic!(),
    }

    // u2 未写入。
    let v = store.save_version().unwrap();
