    assert_eq!(r.body["replaced"], 0);

    // 保存版本 2：v1 仍旧，v1→v2 差异中 u1 出现在 changed。
    let r = request(&s.addr, "POST", "/versions", None);
    let v2 = r.body["id"].as_u64().unwrap();

    let r = request(
        &s.addr,
