    assert_eq!(changed[0]["before"], json!({"id":"u1","name":"Ada","age":36}));
    assert_eq!(changed[0]["after"], json!({"id":"u1","name":"Ada","age":37}));
    let dropped: Vec<_> = r.body["dropped"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| r["id"].as_str().unwrap())
        .collect();
    assert_eq!(dropped, vec!["u3"]);

