166	        let mut current: BTreeMap<String, Vec<Record>> = BTreeMap::new();
167	        let mut versions: Vec<VersionSnap> = Vec::new();
168	
169	        // 1. 恢复最近一次快照（若存在）。
170	        let snap_path = data_dir.join("snapshot.json");
171	        if snap_path.exists() {
172	            let bytes = fs::read(&snap_path).map_err(|e| format!("read snapshot: {e}"))?;
173	            let state: PersistedState =
174	                serde_json::from_slice(&bytes).map_err(|e| format!("parse snapshot: {e}"))?;
175	            for c in state.collections {
176	                current.insert(c.name, c.records);
177	            }
178	            for v in state.versions {
179	                versions.push(VersionSnap {
180	                    id: v.id,
181	                    saved_at: v.saved_at,
182	                    data: v
183	                        .collections
184	                        .into_iter()
185	                        .map(|c| (c.name, c.records))
186	                        .collect(),
187	                });
188	            }
189	        }
190	        let next_id = versions.last().map(|v| v.id + 1).unwrap_or(1);
191	
192	        // 2. 重放快照之后的 WAL，并修复崩溃残留的残缺行。
193	        let wal_path = data_dir.join("wal.log");
194	        let mut valid_bytes = 0usize;
195	        if wal_path.exists() {
196	            let content = fs::read_to_string(&wal_path).map_err(|e| format!("read wal: {e}"))?;
197	            let mut rest = content.as_str();
198	            loop {
199	                if rest.is_empty() {
200	                    break;
201	                }
202	                let Some(nl) = rest.find('\n') else {
203	                    // 最后一行没有换行结尾：本服务的提交总是以换行结尾，故必为残缺行。
204	                    break;
205	                };
206	                let line = &rest[..nl];
207	                match serde_json::from_str::<CommitEvent>(line) {
208	                    Ok(event) => {
209	                        apply_commit(&mut current, event.collection, event.records);
210	                        valid_bytes += nl + 1;
211	                        rest = &rest[nl + 1..];
212	                    }
213	                    Err(_) => break,
214	                }
215	            }
216	            if valid_bytes < content.len() {
217	                let f = fs::OpenOptions::new()
218	                    .write(true)
219	                    .open(&wal_path)
220	                    .map_err(|e| format!("repair wal: {e}"))?;
221	                f.set_len(valid_bytes as u64)
222	                    .map_err(|e| format!("repair wal: {e}"))?;
223	                f.sync_all().ok();
224	            }
225	        }
226	
227	        // 3. 打开 WAL 供后续追加。
228	        let wal = fs::OpenOptions::new()
229	            .create(true)
230	            .append(true)
231	            .open(&wal_path)
232	            .map_err(|e| format!("open wal: {e}"))?;
233	
234	        Ok(Store {
235	            inner: Mutex::new(Inner {
236	                current,
237	                versions,
238	                next_id,
239	                wal,
240	            }),
241	            data_dir,
242	        })
243	    }
